use strict; use warnings;
use File::Find;

my (@decls, @gofiles);
find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $p = $File::Find::name; $p =~ s{^\./}{};
  push @decls, [$p];
}, 'internal');

my %declmap;
for my $d (@decls) {
  my $p = $d->[0];
  open my $fh, '<', $p or next;
  while (my $l = <$fh>) {
    if ($l =~ /^func\s+(\(([^)]*)\)\s*)?([A-Za-z_]\w*)\s*\(/) {
      my $name = $3; my $recv = $2 // '';
      $declmap{"$name\t$p\t" . ($recv ? 'method' : 'func')} = 1;
    }
  }
  close $fh;
}

find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $p = $File::Find::name; $p =~ s{^\./}{};
  return if $p =~ m{^(node_modules|web)/};
  push @gofiles, $p;
}, '.');

my %content;
for my $p (@gofiles) { open my $fh,'<',$p or next; local $/; $content{$p} = <$fh>; close $fh; }

my @res;
for my $key (keys %declmap) {
  my ($name, $path, $kind) = split /\t/, $key;
