  for my $p (@gofiles) {
    my $c = $content{$p} // '';
    my $n = () = $c =~ /$re/g;
    $n-- if $p eq $path;
    if ($n > 0) { $total += $n; $callers{$p} = $n; }
  }
  push @res, [$total, $name, $path, $kind, {%callers}];
}
@res = sort { $b->[0] <=> $a->[0] } @res;
