  my ($dir) = $p =~ m{^(.*)/[^/]+$};
  next if exists $dirpkg{$dir};
  if ($content{$p} && $content{$p} =~ /^package\s+(\w+)/m) { $dirpkg{$dir} = $1; }
}

# declarations: package-level funcs only (no receiver)
my %decl; # "name\tdir" -> path
for my $p (@internal) {
  my ($dir) = $p =~ m{^(.*)/[^/]+$};
  for my $l (split /\n/, $content{$p}//'') {
    if ($l =~ /^func\s+([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\(/) {
      $decl{"$1\t$dir"} = $p;
    }
  }
}

# for each file, map import path -> alias
my %fileimports; # file -> {importpath => alias}
for my $p (@all) {
  my $c = $content{$p}//'';
  my %m;
  while ($c =~ /(?:^|\n)\s*(?:(\w+|\.|_)\s+)?"(github\.com\/usememos\/memos\/[^"]+)"/g) {
    my ($alias,$ip)=($1,$2);
    my $dir = $ip; $dir =~ s{^github\.com/usememos/memos/}{};
    my $a = $alias // ($dirpkg{$dir} // (split m{/}, $dir)[-1]);
    $m{$dir}=$a;
  }
  $fileimports{$p}=\%m;
}

