      $n = () = $c =~ /(?<![\w.])\Q$name\E\s*\(/g;
      # subtract declarations in this file
      my $d = () = $c =~ /^func\s+\Q$name\E\s*(?:\[[^\]]*\])?\(/mg;
      $n -= $d;
    } else {
      my $alias = $fileimports{$p}{$dir};
      next unless defined $alias;
      $n = () = $c =~ /(?<![\w.])\Q$alias\E\.\Q$name\E\s*\(/g;
    }
    if ($n>0){$total+=$n;$callers{$p}=$n;}
  }
  push @res,[$total,$name,$path,{%callers}];
}
